18.09870515509554,33.94446285258228],[-118.09871268651355,33.944473453720846]],[[-118.09891429583175,33.94400724790593],[-118.09892879171154,33.94403018154213],[-118.09886354342582,33.944245411096794],[-118.09882366912956,33.944376941505766],[-118.09892879279329,33.94403018154125],[-118.09891429583175,33.94400724790593]],[[-118.10299621777611,33.947528130039345],[-118.10299244383246,33.94752570275917],[-118.10223232897052,33.94703692406251],[-118.10299621777611,33.947528130039345]],[[-118.10582177357237,33.94175567093885],[-118.10577335638622,33.9417312235816],[-118.10627553467455,33.94198479029196],[-118.10582177357237,33.94175567093885]],[[-118.10585846401992,33.94573915500905],[-118.10584438104885,33.94575881062429],[-118.1062277471543,33.94522375494801],[-118.10585846401992,33.94573915500905]],[[-118.10966537050489,33.956489633221466],[-118.10981277336803,33.95659238087286],[-118.10971557352373,33.956524627045546],[-118.10966537050489,33.956489633221466]],[[-118.11117171213334,33.94890544721176],[-118.11146698828098,33.948504269691256],[-118.11153777587225,33.94840809390142],[-118.11117171213334,33.94890544721176]],[[-118.11262087816785,33.95261574059229],[-118.11209925478471,33.95336949611133],[-118.11210146823514,33.95336629815779],[-118.11262087816785,33.95261574059229]],[[-118.11359589814782,33.939719894973756],[-118.11307925040262,33.94042451913972],[-118.11355771749336,33.93977196764152],[-118.11359589814782,33.939719894973756]],[[-118.11658320285385,33.936967045680056],[-118.11667415661589,33.93701385034499],[-118.11660954047932,33.93698059892862],[-118.11658320285385,33.936967045680056]],[[-118.11705193287268,33.9551950355527],[-118.117049546177,33.95519725110628],[-118.11742278865121,33.9548507866722],[-118.11705193287268,33.9551950355527]],[[-118.11943768118573,33.95294354635123],[-118.11938762025235,33.95299669106741],[-118.11946663429693,33.952912810025616],[-118.11943768118573,33.95294354635123]],[[-118.125125902911,33.94349910721639],[-118.1250309229861,33.943456495221945],[-118.1250149497689,33.943449329356014],[-118.125125902911,33.94349910721639]],[[-118.12559793697326,33.9436579430744],[-118.12559748971609,33.943658803039305],[-118.12557679710235,33.943698625869004],[-118.12559793697326,33.9436579430744]]]}')
  ) AS v(geo_id, name, gj)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b WHERE b.geo_id = v.geo_id AND b.mtfcc = 'X0001');

-- ─── D2. Repoint the two per-office district rows onto their new polygons ──────────────────────────────
UPDATE essentials.districts d SET geo_id = v.geo_id, mtfcc = 'X0001', district_id = v.n
  FROM (VALUES
    ('22ebdde5-9e8d-4a2c-9646-9509e7c6707b'::uuid, 'downey-council-district-2', '2'),
    ('9c06376f-3510-40ee-be67-ca8d84d6ad9e'::uuid, 'downey-council-district-4', '4')
  ) AS v(id, geo_id, n)
 WHERE d.id = v.id;

-- ─── D3. Retitle the two moved offices ──────────────────────────────────────────────────────────────────
UPDATE essentials.offices o SET title = v.title, normalized_position_name = v.title
  FROM (VALUES
    ('cc3bacd0-5026-4914-b271-c6e40c929a9c'::uuid, 'Council Member (District 2)'),
    ('6fa79f0e-a3d8-47f3-b67d-29009818f2ee'::uuid, 'Council Member (District 4)')
  ) AS v(id, title)
 WHERE o.id = v.id;

-- ─── 1. Races ─────────────────────────────────────────────────────────────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, v.oid, v.pos, NULL, v.seats
  FROM (VALUES
    ('59d5c544-b06f-457b-96ed-83be5667ca87'::uuid, 'El Segundo City Council', 2),
    ('cc3bacd0-5026-4914-b271-c6e40c929a9c'::uuid, 'Downey City Council District 2', 1),
    ('6fa79f0e-a3d8-47f3-b67d-29009818f2ee'::uuid, 'Downey City Council District 4', 1)
  ) AS v(oid, pos, seats)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos);

-- ─── 2. Candidates ────────────────────────────────────────────────────────────────────
INSERT INTO essentials.race_candidates
       (race_id, politician_id, full_name, first_name, last_name, is_incumbent, candidate_status, occupational_designation, source)
SELECT r.id, v.pid, v.full_name, v.first_name, v.last_name, v.inc, 'active', v.desig,
       'LA County RR/CC Candidate Statements, November 3 2026 General Election (election 4348), contest ' || v.contest
       || ' (https://apps.lavote.gov/candidate-statements/). Retrieved 2026-10-13. The City Clerk posted no qualified list.'
  FROM (VALUES
    ('El Segundo City Council', '10452', 'Chris Pimentel', 'Chris', 'Pimentel', '1c77d036-8c9e-4831-9bba-40af2d043ed2'::uuid, true, 'Mayor'),
    ('El Segundo City Council', '10452', 'Ryan W. Baldino', 'Ryan', 'Baldino', 'eb515636-52b5-4c48-8052-f60d5d2f4652'::uuid, true, 'Council Member/Attorney'),
    ('El Segundo City Council', '10452', 'John Pickhaver', 'John', 'Pickhaver', NULL::uuid, false, 'Nonprofit CEO/Coach'),
    ('Downey City Council District 2', '10443', 'Hector Sosa', 'Hector', 'Sosa', '92d68971-8cc2-480b-8e29-9938f7a280f1'::uuid, true, 'Downey Councilmember'),
    ('Downey City Council District 2', '10443', 'Maria Zaragoza', 'Maria', 'Zaragoza', NULL::uuid, false, 'Fiscal Analyst/Mother'),
    ('Downey City Council District 4', '10444', 'Martha Camacho Rodriguez', 'Martha', 'Camacho Rodriguez', NULL::uuid, false, 'Teacher'),
    ('Downey City Council District 4', '10444', 'Lissette Rivera', 'Lissette', 'Rivera', NULL::uuid, false, 'Business Woman/CEO'),
    ('Downey City Council District 4', '10444', 'Carrie Uva', 'Carrie', 'Uva', NULL::uuid, false, 'Attorney/Planning Commissioner')
  ) AS v(pos, contest, full_name, first_name, last_name, pid, inc, desig)
  JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
 WHERE NOT EXISTS (SELECT 1 FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND lower(rc.full_name) = lower(v.full_name));

-- ─── 3. Antipartisan: clear the stored party on every linked candidate row ──────────
UPDATE essentials.politicians SET party = NULL
 WHERE party IS NOT NULL AND id IN ('1c77d036-8c9e-4831-9bba-40af2d043ed2', 'eb515636-52b5-4c48-8052-f60d5d2f4652', '92d68971-8cc2-480b-8e29-9938f7a280f1');

-- ─── 4. Post-verify gate ──────────────────────────────────────────────────────────────
DO $$
DECLARE
  pos text[] := ARRAY['El Segundo City Council', 'Downey City Council District 2', 'Downey City Council District 4'];
  n_races int; n_cands int; n_null int; n_party int; n_badcount int; n_incseat int; n_unreach int; n_pparty int;
  n_d2 int; n_d4 int; n_wrong int; n_downey int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL), count(*) FILTER (WHERE r.primary_party IS NOT NULL)
    INTO n_races, n_null, n_party FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_cands FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  -- each race carries exactly the county field, on the expected seat count
  SELECT count(*) INTO n_badcount FROM (VALUES
      ('El Segundo City Council', 2, 3, 2), ('Downey City Council District 2', 1, 2, 1), ('Downey City Council District 4', 1, 3, 0)
    ) AS v(pos, seats, n_cand, n_inc)
    LEFT JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
   WHERE r.id IS NULL OR r.seats <> v.seats
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id) <> v.n_cand
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) <> v.n_inc;
  -- every incumbent is linked and currently holds a seat on the race's own district polygon
  SELECT count(*) INTO n_incseat FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND rc.is_incumbent
     AND (rc.politician_id IS NULL OR NOT EXISTS (
       SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
         JOIN essentials.districts d2 ON d2.id = o2.district_id
        WHERE och.politician_id = rc.politician_id
          AND d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)));
  -- END TO END: an interior point of each race's own polygon reaches that race
  SELECT count(*) INTO n_unreach FROM essentials.races r
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb
                      WHERE gb.geo_id = d.geo_id AND gb.mtfcc = d.mtfcc
                        AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(gb.geometry)));
  SELECT count(*) INTO n_pparty FROM essentials.politicians p WHERE p.party IS NOT NULL AND p.id IN (
    SELECT rc.politician_id FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
     WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND rc.politician_id IS NOT NULL);
  -- Downey: the D2 and D4 polygons sit inside the city and do not overlap each other
  SELECT count(*) INTO n_d2 FROM essentials.geofence_boundaries b JOIN essentials.geofence_boundaries p ON p.geo_id = '0619766' AND p.mtfcc = 'G4110'
   WHERE b.geo_id = 'downey-council-district-2' AND b.mtfcc = 'X0001'
     AND public.ST_Area(public.ST_Intersection(b.geometry, p.geometry)) / public.ST_Area(b.geometry) > 0.995;
  SELECT count(*) INTO n_d4 FROM essentials.geofence_boundaries b JOIN essentials.geofence_boundaries p ON p.geo_id = '0619766' AND p.mtfcc = 'G4110'
   WHERE b.geo_id = 'downey-council-district-4' AND b.mtfcc = 'X0001'
     AND public.ST_Area(public.ST_Intersection(b.geometry, p.geometry)) / public.ST_Area(b.geometry) > 0.995;
  SELECT count(*) INTO n_wrong FROM essentials.geofence_boundaries a JOIN essentials.geofence_boundaries b
      ON a.geo_id = 'downey-council-district-2' AND b.geo_id = 'downey-council-district-4' AND a.mtfcc = 'X0001' AND b.mtfcc = 'X0001'
   WHERE public.ST_Area(public.ST_Intersection(a.geometry, b.geometry)) > 1e-8;
  -- Downey council still has its five sitting members
  SELECT count(DISTINCT och.politician_id) INTO n_downey FROM essentials.office_current_holder och
    JOIN essentials.offices o ON o.id = och.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.id IN ('22ebdde5-9e8d-4a2c-9646-9509e7c6707b', '9c06376f-3510-40ee-be67-ca8d84d6ad9e', '39e05679-110c-48be-be51-5434b5da6727',
                  '8468daf6-6faa-49f2-b034-af135d008300', '996396b2-872e-4d83-a9fb-27d57acdcb4c');
  IF n_races <> 3 THEN RAISE EXCEPTION 'expected 3 races, got %', n_races; END IF;
  IF n_cands <> 8 THEN RAISE EXCEPTION 'expected 8 candidates, got %', n_cands; END IF;
  IF n_null <> 0 OR n_party <> 0 THEN RAISE EXCEPTION 'office-less (%) or partisan (%) race', n_null, n_party; END IF;
  IF n_badcount <> 0 THEN RAISE EXCEPTION '% race(s) whose seats / candidates / incumbents differ from the county list', n_badcount; END IF;
  IF n_incseat <> 0 THEN RAISE EXCEPTION '% incumbent(s) unlinked or not holding a seat on their race polygon', n_incseat; END IF;
  IF n_unreach <> 0 THEN RAISE EXCEPTION '% race(s) not reachable from inside their own polygon', n_unreach; END IF;
  IF n_pparty <> 0 THEN RAISE EXCEPTION '% linked candidate row(s) still carry a party', n_pparty; END IF;
  IF n_d2 <> 1 OR n_d4 <> 1 THEN RAISE EXCEPTION 'Downey district polygon missing or outside the city (D2 %, D4 %)', n_d2, n_d4; END IF;
  IF n_wrong <> 0 THEN RAISE EXCEPTION 'Downey D2 and D4 polygons overlap'; END IF;
  IF n_downey <> 5 THEN RAISE EXCEPTION 'Downey council has % sitting members, expected 5', n_downey; END IF;
  RAISE NOTICE 'CA_0307 applied: % races, % candidates', n_races, n_cands;
END $$;

COMMIT;
